t=np.arange(180);rng=np.random.default_rng(15);s=np.zeros(180);[s.__setitem__(i,.88*s[i-1]+rng.normal(0,.018)) for i in range(1,180)];sd=s.std();ax.plot(t,s,color=ACCENT,lw=1.5);ax.axhline(2*sd,color=BAD,ls='--');ax.axhline(-2*sd,color=BAD,ls='--');ax.axhline(0,color=INK,lw=1);ax.set_xlabel('trading day');ax.set_ylabel('spread (log-price)');ax.set_title('Bands define entries only after parameters are frozen',loc='left')
